/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:axis:set:domain' );


// MAIN //

/**
* Sets a boolean flag indicating whether the axis baseline should be included as part of the axis.
*
* @private
* @param {boolean} value - input value
* @throws {TypeError} must be a boolean
* @returns {void}
*/
function set( value ) {
	if ( !isBoolean( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a boolean. Value: `%s`.', 'domain', value ) );
	}
	if ( value !== this._domain ) {
		debug( 'Current value: %s. New value: %s.', this._domain, value );
		this._domain = value;
		this.emit( 'change' );
	}
}


// EXPORTS //

module.exports = set;
